\label{conj:integer rank}
  For any $r\in\Z_{\geq 2}$ there exists a unique formal series 
  \begin{equation}\label{eq:conjectural-integer-series}
    |I^{(r)}\rangle =c_1^{\nu_1}\cdots c_r^{\nu_r} \exp\left(\sum_{k=0}^{r-1} \frac{g_k(c_1,\ldots,c_{r-1})}{c_r^k}\right)
    \sum_{k=0}^\infty c_r^k v_k  
  \end{equation}
  satisfying 
  \begin{equation}\label{eq_irregular_condition_integer}
    L_n |I^{(r)}\rangle=\left(\Lambda_n+\sum_{k=1}^{r-n}k c_{n+k}\frac{\partial}{\partial c_k}\right) 
    |I^{(r)}\rangle\quad (n>0),\quad 
    L_0|I^{(r)}\rangle=\left(\Delta_{c_0}+\sum_{k=1}^rkc_k\frac{\partial}{\partial c_k}\right)
    |I^{(r)}\rangle,  
  \end{equation}
  where $v_0$ is an irregular vector $|I^{(r-1)}\rangle$ of rank $r-1$  satisfying the relations
  \begin{align*}
    L_n |I^{(r-1)}\rangle=\left(\Lambda_n'+\sum_{k=1}^{r-n}k c_{n+k}\frac{\partial}{\partial c_k}\right) 
    |I^{(r-1)}\rangle\quad (n>0),\quad 
    L_0|I^{(r-1)}\rangle=\left(\Delta_{c_0'}+\sum_{k=1}^rkc_k\frac{\partial}{\partial c_k}\right)
    |I^{(r-1)}\rangle, 
  \end{align*}
  where \begin{equation*}
    \Lambda_n'=((n+1)Q-c_0')c_n-\sum_{k=1}^{n-1} c_k c_{n-k},  \quad c_j=0 \text{ for } j\geq r,  
\end{equation*} 
and $v_k$ are descendants of $v_0=|I^{(r-1)}\rangle$.

