\end{equation*}
where $c_k = O(k)$, $r_k(n)$ is a "small" remainder (possibly $O(1)$).

For even $k \ge 6$, we conjecture that, for all sufficiently large $n$, the sequence $s_k(n)$ follows a single periodic pattern of odd values. Let
\begin{equation*}
    C_k = \frac{k(k-1)}{2} - 5,
    \qquad
    m = (2n + C_k) \bmod (k-1).
\end{equation*}
Then
\begin{equation*}
    s_k(n) = m + \big(1 - (m \bmod 2)\big)
    + \left\lfloor \frac{1}{|m - (k-2)| + 1} \right\rfloor
    + 2\left\lfloor \frac{1}{|m - (k-3)| + 1} \right\rfloor.
\end{equation*}

For odd $k \ge 7$, we conjecture that, for all sufficiently large $n$, the sequence $s_k(n)$ follows a two-half alternating periodic pattern, where each half has length
\begin{equation*}
    H = \frac{k-1}{2}.
\end{equation*}
Let
\begin{equation*}
    C_k = \frac{(k-1)^2}{2} - 4,
    \qquad
    m = \left(n + \frac{C_k}{2} + H\right) \bmod (k-1).
\end{equation*}
Define the two correction locations by
\begin{equation*}
    (m_{\mathrm{origin}}, m_{\mathrm{spike}}) =
    \begin{cases}
        (H,\, 2H-1), & k \equiv 1 \pmod{4},\\
        (0,\, H-1), & k \equiv 3 \pmod{4}.
    \end{cases}
\end{equation*}
Then
\begin{equation*}
    s_k(n) = m + \big(1 - (m \bmod 2)\big)
    + \left\lfloor \frac{1}{|m - m_{\mathrm{origin}}| + 1} \right\rfloor
    + 2\left\lfloor \frac{1}{|m - m_{\mathrm{spike}}| + 1} \right\rfloor.
\end{equation*}

