    Let \(G\) be a graph and write $d_v\defeq \deg_G(v)$. Then for any antiferromagnetic edge-weighted graph $H$,
    \begin{equation}\label{eq:afm}
        \hom(G,H)\geq \prod_{v\in V(G)}\hom(K_{d_v+1},H)^{\frac{1}{d_v+1}}.
    \end{equation}

\label{conj:QCYBE trans 1,-1}
Let~$R$ be any solution of QYBE. Then
for any transitive $n\times n$-matrix $\boldsymbol{\epsilon}=(\epsilon_{i,j})_{1\le i,j\le n}$ with~$\epsilon_{i,j}\in\{1,-1\}$, $1\le i,j\le n$,
\begin{equation}\label{eq:R eps defn}
\mathbf R^{(\boldsymbol{\epsilon})}:=
(R_{1,2n}^{(\epsilon_{n,1})}\cdots 
R_{n,2n}^{(\epsilon_{n,n})}) 
(R_{1,2n-1}^{(\epsilon_{n-1,1})}\cdots 
R_{n,2n-1}^{(\epsilon_{n-1,n})})
\cdots (R_{1,n+1}^{(\epsilon_{1,1})}\cdots R_{n,n+1}^{(\epsilon_{1,n})})
\end{equation}
solves QYBE.

\label{conj:K n n-2}
$\tstirling{\vec K_n}{n-2}=(n-2)\binom{2n-3}n+\binom{2(n-2)}n$
for all~$n\ge 3$.

{\label{conj-low-deg}}
    For ``natural'' high-dimensional hypothesis testing problems between $\Pb$ and $\Qb$, the following statements hold.
    \begin{enumerate}
        \item[(1)] If $\mathsf{Adv}_{\leq D}(\Pb\|\Qb)=O(1)$ as $n\to\infty$, then there exists a constant $C$ such that no algorithm with running time $N^{D/(\log N)^C}$ that achieves strong detection between $\Pb$ and $\Qb$. 
